import { useEffect, useState, type ReactElement } from 'react';
import { Dialog, type DialogProps, Button, Input } from '@design-schema/react';

function DialogHarness({ open: initialOpen, onClose, ...rest }: DialogProps): ReactElement {
  const [open, setOpen] = useState(initialOpen);
  useEffect(() => setOpen(initialOpen), [initialOpen]);

  return (
    <>
      <Button label={rest.heading} onClick={() => setOpen(true)} />
      <Dialog
        {...rest}
        open={open}
        onClose={(reason) => {
          onClose?.(reason);
          setOpen(false);
        }}
      />
    </>
  );
}

const renameFooter = (
  <>
    <Button label="Rename" variant="primary" />
    <Button label="Cancel" variant="secondary" />
  </>
);

<DialogHarness open heading="Rename project" footer={renameFooter}><Input label="Project name" name="projectName" defaultValue="Q3 roadmap" /></DialogHarness>

